package kr.yuumi97.core.rpg;
import org.bukkit.*;import org.bukkit.entity.*;import org.bukkit.event.*;import org.bukkit.event.entity.*;import org.bukkit.inventory.ItemStack;import org.bukkit.persistence.PersistentDataType;import java.util.*;import java.util.concurrent.ThreadLocalRandom;

/** All post-hit mechanics consume one final accepted amount, including managed logical HP. */
public final class CombatDamageService implements Listener {
 public enum DamageKind { NORMAL,PRIMARY,FINISHER,RUNE,DOT,REPLAY,NATIVE }
 private static final class Context{final DamageKind kind;final ItemStack weapon;final Player source;final LivingEntity target;double actual;Context(DamageKind k,ItemStack w,Player p,LivingEntity t){kind=k;weapon=w;source=p;target=t;}}private final RpgJobManager r;private final Deque<Context> contexts=new ArrayDeque<>();private final Map<UUID,ItemStack> projectiles=new HashMap<>();private final Map<UUID,Long> runeReady=new HashMap<>(),leechReady=new HashMap<>();
 private final Set<UUID> dead=new HashSet<>();CombatDamageService(RpgJobManager r){this.r=r;if(Bukkit.getPluginManager().isPluginEnabled("AuraSkills"))Bukkit.getPluginManager().registerEvents(new AuraReplayGuard(this),r.plugin);}public boolean isSecondaryDamage(){return !contexts.isEmpty();}public DamageKind currentKind(){return contexts.isEmpty()?DamageKind.NATIVE:contexts.peek().kind;}public ItemStack shotWeapon(Projectile e){return projectiles.get(e.getUniqueId());}
 /** AuraSkills fires this synchronously from native HIGH, before dungeon/raid HIGHEST HP accounting. */
 private static final class AuraReplayGuard implements Listener{private final CombatDamageService damage;AuraReplayGuard(CombatDamageService damage){this.damage=damage;}
  @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void replay(dev.aurelium.auraskills.api.event.damage.DamageEvent event){Context context=damage.contexts.peek();if(context==null||context.kind!=DamageKind.REPLAY)return;var meta=event.getDamageMeta();if(context.source.equals(meta.getAttackerAsPlayer())&&context.target.equals(meta.getTarget()))meta.clearAttackModifiers();}}
 public double budget(Player p,double base,DamageKind kind){int star=r.holdingSignature(p)?r.getSignatures().star(p.getInventory().getItemInMainHand()):0;double[] bonus={0,1,1.8,2.6,3.6,4.6,5.6,7};List<Double> configured=r.plugin.getConfig().getDoubleList("forge.weapon-damage");double forge=configured.size()>star?configured.get(star):bonus[star];return RpgRules.damageBudget(base,forge,r.combatLevel(p),r.cfg("rpg.growth.per-level",.025),kind==DamageKind.PRIMARY,r.cfg("rpg.milestones.primary15",.10));}
 public double hit(Player p,LivingEntity target,double base,DamageKind kind){return scaledHit(p,target,budget(p,base,kind),kind);}
 public double scaledHit(Player p,LivingEntity target,double amount,DamageKind kind){return projectileHit(p,target,amount,kind,p.getInventory().getItemInMainHand());}
 public double projectileHit(Player p,LivingEntity target,double amount,DamageKind kind,ItemStack weapon){if(!r.hostile(p,target)||!RpgJobManager.usable(p)||amount<=0)return 0;double crit=r.combatSkills().critical(p,target,kind)?1.5:r.hasCharm(p,"charm_crimson_claw")&&ThreadLocalRandom.current().nextDouble()<.15?1.45:1;
  amount*=crit*(1+r.combatSkills().vulnerability(target))*(1+Math.max(r.getWorkshop().feastEffect(p,"VALOR","damage",.15),r.lifeSkills().damageBonus(p))+r.combatSkills().attackBlessing(p));if(r.hasCharm(p,"charm_crimson_claw")&&r.isBoss(target))amount*=1.12;return apply(p,target,amount,kind,weapon);}
 public double raw(Player p,LivingEntity target,double amount,DamageKind kind){return apply(p,target,amount,kind,p.getInventory().getItemInMainHand());}
 private double apply(Player p,LivingEntity target,double amount,DamageKind kind,ItemStack weapon){if(!r.hostile(p,target)||!RpgJobManager.usable(p)||!Double.isFinite(amount)||amount<=0)return 0;Context c=new Context(kind,weapon.clone(),p,target);contexts.push(c);try{target.setNoDamageTicks(0);target.damage(amount,p);return c.actual;}finally{contexts.pop();}}
 private Player player(EntityDamageEvent e){if(e instanceof EntityDamageByEntityEvent hit){if(hit.getDamager() instanceof Player p)return p;if(hit.getDamager() instanceof Projectile projectile&&projectile.getShooter() instanceof Player p)return p;}if(r.isTrainingDummy(e.getEntity())){String key=e.getCause()==EntityDamageEvent.DamageCause.POISON?"yuumi_training_poison_owner":e.getCause()==EntityDamageEvent.DamageCause.FIRE_TICK?"yuumi_training_fire_owner":null;if(key!=null){String id=e.getEntity().getPersistentDataContainer().get(new NamespacedKey(r.plugin,key),PersistentDataType.STRING);try{return id==null?null:Bukkit.getPlayer(UUID.fromString(id));}catch(IllegalArgumentException ignored){}}}return null;}
 @EventHandler(priority=EventPriority.MONITOR) public void accepted(EntityDamageEvent event){double managed=r.acceptedDamage(event);if(event.isCancelled()&&managed<0||!(event.getEntity() instanceof LivingEntity target)||target instanceof Player)return;double actual=managed>=0?managed:Math.min(event.getFinalDamage(),target.getHealth()+target.getAbsorptionAmount());if(!Double.isFinite(actual)||actual<=0)return;
  Context c=contexts.peek();DamageKind kind=c!=null?c.kind:event instanceof EntityDamageByEntityEvent?DamageKind.NATIVE:DamageKind.DOT;r.combatSkills().accumulateEchoDamage(target,actual,kind);Player p=player(event);if(p==null||managed<0&&!r.hostile(p,target))return;if(c!=null)c.actual+=actual;ItemStack weapon=c!=null?c.weapon:event instanceof EntityDamageByEntityEvent by&&by.getDamager() instanceof Projectile projectile?projectiles.getOrDefault(projectile.getUniqueId(),p.getInventory().getItemInMainHand()):p.getInventory().getItemInMainHand();
  r.combatSkills().accepted(p,target,actual,kind);if(kind!=DamageKind.REPLAY){double extra=r.perk(p,RpgDomain.COMBAT,"poise")*r.cfg("rpg.perks.poise.per-rank",.10);if(extra>0)r.damagePoise(p,target,actual*extra);}
  long now=System.currentTimeMillis();double rate=(r.hasCharm(p,"charm_vampiric_purr")?.06:0)+r.perk(p,RpgDomain.COMBAT,"leech")*r.cfg("rpg.perks.leech.per-rank",.01);if(kind!=DamageKind.REPLAY&&rate>0&&now>=leechReady.getOrDefault(p.getUniqueId(),0L)){r.combatSkills().heal(p,p,actual*rate,false);leechReady.put(p.getUniqueId(),now+500);}
  if(!target.isDead()&&(kind==DamageKind.NORMAL||kind==DamageKind.PRIMARY||kind==DamageKind.NATIVE)){proc(p,target,weapon);r.lifeSkills().acceptedAttack(p,target);}if(target.isDead())killed(p,target);
 }
 public void killed(Player p,LivingEntity target){if(r.isTrainingDummy(target)||p.getGameMode()==GameMode.CREATIVE||p.getGameMode()==GameMode.SPECTATOR||!dead.add(target.getUniqueId()))return;r.combatSkills().killed(p,target);r.awardCombatXp(p,(int)r.cfg("rpg.xp.kill",12));double base=r.cfg("rpg.drops.monster_soul_core."+(r.getCombat(p)!=null?"specialist":"base"),r.getCombat(p)!=null?.14:.04);double chance=base*(1+r.perk(p,RpgDomain.LIFE,"luck")*r.cfg("rpg.perks.luck.per-rank",.05))*(1+r.getWorkshop().feastEffect(p,"HARVEST","drop",.15));if(ThreadLocalRandom.current().nextDouble()<chance)r.deliver(p,r.items.create("monster_soul_core"));Bukkit.getScheduler().runTaskLater(r.plugin,()->dead.remove(target.getUniqueId()),200);}
 private void proc(Player p,LivingEntity target,ItemStack weapon){if(weapon==null||!weapon.hasItemMeta())return;var pdc=weapon.getItemMeta().getPersistentDataContainer();String type=pdc.get(new NamespacedKey(r.plugin,"yuumi_rune_type"),PersistentDataType.STRING);long now=System.currentTimeMillis();if(type==null||now<runeReady.getOrDefault(p.getUniqueId(),0L)||ThreadLocalRandom.current().nextDouble()>=r.cfg("runes."+type+".proc-chance",type.equals("THUNDER")?.15:.20))return;
  double q=pdc.getOrDefault(new NamespacedKey(r.plugin,"yuumi_rune_masterwork"),PersistentDataType.INTEGER,0)==1?1.25:1;runeReady.put(p.getUniqueId(),now+(long)(r.cfg("runes."+type+".cooldown-seconds",3)*1000));
  switch(type){case "FIRE"->{raw(p,target,r.cfg("runes.FIRE.damage",4)*q,DamageKind.RUNE);if(r.taggedEnemy(target)||r.isBoss(target))r.combatSkills().repeat(p,RpgDomain.COMBAT,(int)Math.ceil(r.cfg("runes.FIRE.duration-seconds",3)*q),20,n->{if(target.isValid()&&!target.isDead())raw(p,target,r.cfg("runes.FIRE.burn-damage",1)*q,DamageKind.DOT);},null);else Bukkit.getScheduler().runTask(r.plugin,()->{if(!target.isValid()||target.isDead())return;int ticks=(int)(20*r.cfg("runes.FIRE.duration-seconds",3)*q);target.setFireTicks(Math.max(target.getFireTicks(),ticks));if(r.isTrainingDummy(target)){target.getPersistentDataContainer().set(new NamespacedKey(r.plugin,"yuumi_training_fire_owner"),PersistentDataType.STRING,p.getUniqueId().toString());target.getPersistentDataContainer().set(new NamespacedKey(r.plugin,"yuumi_training_fire_expires"),PersistentDataType.LONG,System.nanoTime()+ticks*50_000_000L);}});}
   case "FROST"->{raw(p,target,r.cfg("runes.FROST.damage",3)*q,DamageKind.RUNE);target.addPotionEffect(new org.bukkit.potion.PotionEffect(org.bukkit.potion.PotionEffectType.SLOWNESS,(int)(40*q),1));r.combatSkills().freeze(target,(int)(10*q));}
   case "THUNDER"->{raw(p,target,r.cfg("runes.THUNDER.damage",3)*q,DamageKind.RUNE);int count=0;for(LivingEntity e:r.combatSkills().enemies(p,target.getLocation(),r.cfg("runes.THUNDER.radius",5)))if(!e.equals(target)){raw(p,e,r.cfg("runes.THUNDER.damage",3)*q,DamageKind.RUNE);if(++count==2)break;}}
  }
 }
 @EventHandler(ignoreCancelled=true) public void shoot(EntityShootBowEvent e){if(e.getEntity() instanceof Player&&e.getProjectile() instanceof Projectile projectile&&e.getBow()!=null){projectiles.put(projectile.getUniqueId(),e.getBow().clone());Bukkit.getScheduler().runTaskLater(r.plugin,()->projectiles.remove(projectile.getUniqueId()),1200);}}
 @EventHandler public void hit(ProjectileHitEvent e){Bukkit.getScheduler().runTask(r.plugin,()->projectiles.remove(e.getEntity().getUniqueId()));}
}
